      "רַבִּי יִשְׁמָעֵאל אוֹמֵר, הָעֹמֶר הָיָה בָא בְשַׁבָּת מִשָּׁלשׁ סְאִין, וּבְחֹל מֵחָמֵשׁ. וַחֲכָמִים אוֹמְרִים, אֶחָד בְּשַׁבָּת וְאֶחָד בְּחֹל, מִשָּׁלשׁ הָיָה בָא. רַבִּי חֲנִינָא סְגָן הַכֹּהֲנִים אוֹמֵר, בְּשַׁבָּת הָיָה נִקְצָר בְּיָחִיד וּבְמַגָּל אֶחָד וּבְקֻפָּה אַחַת. וּבְחֹל, בִּשְׁלשָׁה וּבְשָׁלשׁ קֻפּוֹת וּבְשָׁלשׁ מַגָּלוֹת. וַחֲכָמִים אוֹמְרִים, אֶחָד בְּשַׁבָּת וְאֶחָד בְּחֹל, בִּשְׁלשָׁה וּבְשָׁלשׁ קֻפּוֹת וּבְשָׁלשׁ מַגָּלוֹת:",
      "מִצְוַת הָעֹמֶר לָבֹא מִן הַקָּרוֹב. לֹא בִכֵּר הַקָּרוֹב לִירוּשָׁלַיִם, מְבִיאִים אוֹתוֹ מִכָּל מָקוֹם. מַעֲשֶׂה שֶׁבָּא מִגַּגּוֹת צְרִיפִין, וּשְׁתֵּי הַלֶּחֶם מִבִּקְעַת עֵין סוֹכֵר:",
      "כֵּיצַד הָיוּ עוֹשִׂים. שְׁלוּחֵי בֵית דִּין יוֹצְאִים מֵעֶרֶב יוֹם טוֹב, וְעוֹשִׂים אוֹתוֹ כְרִיכוֹת בִּמְחֻבָּר לַקַּרְקַע, כְּדֵי שֶׁיְּהֵא נוֹחַ לִקְצֹר. וְכָל הָעֲיָרוֹת הַסְּמוּכוֹת לְשָׁם, מִתְכַּנְּסוֹת לְשָׁם, כְּדֵי שֶׁיְּהֵא נִקְצָר בְּעֵסֶק גָּדוֹל. כֵּיוָן שֶׁחֲשֵׁכָה, אוֹמֵר לָהֶם, בָּא הַשָּׁמֶשׁ, אוֹמְרִים, הֵן. בָּא הַשָּׁמֶשׁ, אוֹמְרִים הֵן. מַגָּל זוֹ, אוֹמְרִים הֵן. מַגָּל זוֹ, אוֹמְרִים הֵן. קֻפָּה זוֹ, אוֹמְרִים הֵן. קֻפָּה זוֹ, אוֹמְרִים הֵן. בְּשַׁבָּת אוֹמֵר לָהֶם, שַׁבָּת זוֹ, אוֹמְרִים הֵן. שַׁבָּת זוֹ, אוֹמְרִים הֵן. אֶקְצֹר, וְהֵם אוֹמְרִים לוֹ קְצֹר. אֶקְצֹר, וְהֵם אוֹמְרִים לוֹ קְצֹר. שָׁלשׁ פְּעָמִים עַל כָּל דָּבָר וְדָבָר, וְהֵם אוֹמְרִים לוֹ הֵן, הֵן, הֵן. וְכָל כָּךְ לָמָּה. מִפְּנֵי הַבַּיְתוֹסִים, שֶׁהָיוּ אוֹמְרִים, אֵין קְצִירַת הָעֹמֶר בְּמוֹצָאֵי יוֹם טוֹב:",
      "קְצָרוּהוּ וּנְתָנוּהוּ בְקֻפּוֹת, הֱבִיאוּהוּ לָעֲזָרָה, הָיוּ מְהַבְהְבִין אוֹתוֹ בָאוּר, כְּדֵי לְקַיֵּם בּוֹ מִצְוַת קָלִי, דִּבְרֵי רַבִּי מֵאִיר. וַחֲכָמִים אוֹמְרִים, בְּקָנִים וּבִקְלִיחוֹת חוֹבְטִים אוֹתוֹ, כְּדֵי שֶׁלֹּא יִתְמָעֵךְ. נְתָנוּהוּ לָאַבּוּב, וְאַבּוּב הָיָה מְנֻקָּב, כְּדֵי שֶׁיְּהֵא הָאוּר שׁוֹלֵט בְּכֻלּוֹ. שְׁטָחוּהוּ בָעֲזָרָה, וְהָרוּחַ מְנַשֶּׁבֶת בּוֹ. נְתָנוּהוּ בְרֵחַיִם שֶׁל גָּרוֹסוֹת, וְהוֹצִיאוּ מִמֶּנּוּ עִשָּׂרוֹן שֶׁהוּא מְנֻפֶּה מִשְּׁלשׁ עֶשְׂרֵה נָפָה, וְהַשְּׁאָר נִפְדֶּה וְנֶאֱכָל לְכָל אָדָם. וְחַיָּב בַּחַלָּה, וּפָטוּר מִן הַמַּעַשְׂרוֹת. רַבִּי עֲקִיבָא מְחַיֵּב בַּחַלָּה וּבַמַּעַשְׂרוֹת. בָא לוֹ לָעִשָּׂרוֹן, וְנָתַן שַׁמְנוֹ וּלְבוֹנָתוֹ, יָצַק, וּבָלַל, הֵנִיף, וְהִגִּישׁ, וְקָמַץ, וְהִקְטִיר, וְהַשְּׁאָר נֶאֱכָל לַכֹּהֲנִים:",
      "מִשֶּׁקָּרַב הָעֹמֶר, יוֹצְאִין וּמוֹצְאִין שׁוּק יְרוּשָׁלַיִם שֶׁהוּא מָלֵא קֶמַח וְקָלִי, שֶׁלֹּא בִרְצוֹן חֲכָמִים, דִּבְרֵי רַבִּי מֵאִיר. רַבִּי יְהוּדָה אוֹמֵר, בִּרְצוֹן חֲכָמִים הָיוּ עוֹשִׂים. מִשֶּׁקָּרַב הָעֹמֶר, הֻתַּר הֶחָדָשׁ מִיָּד, וְהָרְחוֹקִים מֻתָּרִים מֵחֲצוֹת הַיּוֹם וּלְהַלָּן. מִשֶּׁחָרַב בֵּית הַמִּקְדָּשׁ, הִתְקִין רַבָּן יוֹחָנָן בֶּן זַכַּאי, שֶׁיְּהֵא יוֹם הָנֵף כֻּלּוֹ אָסוּר. אָמַר רַבִּי יְהוּדָה, וַהֲלֹא מִן הַתּוֹרָה הוּא אָסוּר, שֶׁנֶּאֱמַר (ויקרא כג), עַד עֶצֶם הַיּוֹם הַזֶּה. מִפְּנֵי מָה הָרְחוֹקִים מֻתָּרִים מֵחֲצוֹת הַיּוֹם וּלְהַלָּן, מִפְּנֵי שֶׁהֵן יוֹדְעִין שֶׁאֵין בֵּית דִּין מִתְעַצְּלִין בּוֹ:",
      "הָעֹמֶר הָיָה מַתִּיר בַּמְּדִינָה, וּשְׁתֵּי הַלֶּחֶם בַּמִּקְדָּשׁ. אֵין מְבִיאִין מְנָחוֹת וּבִכּוּרִים וּמִנְחַת בְּהֵמָה קֹדֶם לָעֹמֶר. וְאִם הֵבִיא, פָּסוּל. קֹדֶם לִשְׁתֵּי הַלֶּחֶם, לֹא יָבִיא. וְאִם הֵבִיא, כָּשֵׁר:",
      "הַחִטִּים וְהַשְּׂעֹרִים וְהַכֻּסְּמִין וְשִׁבֹּלֶת שׁוּעָל וְהַשִּׁיפוֹן חַיָּבִין בַּחַלָּה, וּמִצְטָרְפִין זֶה עִם זֶה, וַאֲסוּרִים בֶּחָדָשׁ מִלִּפְנֵי הַפֶּסַח, וּמִלִּקְצֹר מִלִּפְנֵי הָעֹמֶר. וְאִם הִשְׁרִישׁוּ קֹדֶם לָעֹמֶר, הָעֹמֶר מַתִּירָן. וְאִם לָאו, אֲסוּרִים עַד שֶׁיָּבֹא עֹמֶר הַבָּא:",
      "קוֹצְרִים בֵּית הַשְּׁלָחִים שֶׁבָּעֲמָקִים, אֲבָל לֹא גוֹדְשִׁין. אַנְשֵׁי יְרִיחוֹ קוֹצְרִין בִּרְצוֹן חֲכָמִים, וְגוֹדְשִׁין שֶׁלֹּא בִרְצוֹן חֲכָמִים, וְלֹא מִחוּ בְיָדָם חֲכָמִים. קוֹצֵר לַשַּׁחַת, וּמַאֲכִיל לַבְּהֵמָה. אָמַר רַבִּי יְהוּדָה, אֵימָתַי, בִּזְמַן שֶׁהִתְחִיל עַד שֶׁלֹּא הֵבִיאָה שְׁלִישׁ. רַבִּי שִׁמְעוֹן אוֹמֵר, אַף יִקְצֹר וְיַאֲכִיל אַף מִשֶּׁהֵבִיאָה שְׁלִישׁ:",
      "קוֹצְרִין מִפְּנֵי הַנְּטִיעוֹת, מִפְּנֵי בֵית הָאֵבֶל, מִפְּנֵי בִטּוּל בֵּית הַמִּדְרָשׁ. לֹא יַעֲשֶׂה אוֹתָן כְּרִיכוֹת, אֲבָל מַנִּיחָן צְבָתִים. מִצְוַת הָעֹמֶר לָבֹא מִן הַקָּמָה. לֹא מָצָא, יָבִיא מִן הָעֳמָרִים. מִצְוָתוֹ לָבֹא מִן הַלַּח. לֹא מָצָא, יָבִיא מִן הַיָּבֵשׁ. מִצְוָתוֹ לִקְצֹר בַּלַּיְלָה. נִקְצַר בַּיּוֹם, כָּשֵׁר. וְדוֹחֶה אֶת הַשַּׁבָּת:"
