      "אָמַר לָהֶם הַמְמֻנֶּה, בֹּאוּ וְהָפִיסוּ, מִי שׁוֹחֵט, מִי זוֹרֵק, מִי מְדַשֵּׁן מִזְבֵּחַ הַפְּנִימִי, מִי מְדַשֵּׁן אֶת הַמְּנוֹרָה, מִי מַעֲלֶה אֵבָרִים לַכֶּבֶשׁ, הָרֹאשׁ וְהָרֶגֶל, וּשְׁתֵּי הַיָּדַיִם, הָעֹקֶץ וְהָרֶגֶל, הֶחָזֶה וְהַגֵּרָה, וּשְׁתֵּי דְפָנוֹת, הַקְּרָבַיִם, וְהַסֹּלֶת, וְהַחֲבִתִּים, וְהַיָּיִן. הֵפִיסוּ, זָכָה מִי שֶׁזָּכָה:",
      "אָמַר לָהֶם הַמְמֻנֶּה, צְאוּ וּרְאוּ אִם הִגִּיעַ זְמַן הַשְּׁחִיטָה. אִם הִגִּיעַ, הָרוֹאֶה אוֹמֵר, בַּרְקַאי. מַתְיָא בֶן שְׁמוּאֵל אוֹמֵר, הֵאִיר פְּנֵי כָל הַמִּזְרָח. עַד שֶׁהוּא בְחֶבְרוֹן, וְהוּא אוֹמֵר, הֵין:",
      "אָמַר לָהֶם, צְאוּ וְהָבִיאוּ טָלֶה מִלִּשְׁכַּת הַטְּלָאִים. וַהֲרֵי לִשְׁכַּת הַטְּלָאִים הָיְתָה בְמִקְצוֹעַ צְפוֹנִית מַעֲרָבִית. וְאַרְבַּע לְשָׁכוֹת הָיוּ שָׁם, אַחַת לִשְׁכַּת הַטְּלָאִים, וְאַחַת לִשְׁכַּת הַחוֹתָמוֹת, וְאַחַת לִשְׁכַּת בֵּית הַמּוֹקֵד, וְאַחַת לִשְׁכָּה שֶׁהָיוּ עוֹשִׂין בָּהּ לֶחֶם הַפָּנִים:",
      "נִכְנְסוּ לְלִשְׁכַּת הַכֵּלִים, וְהוֹצִיאוּ מִשָּׁם תִּשְׁעִים וּשְׁלשָׁה כְלֵי כֶסֶף וּכְלֵי זָהָב. הִשְׁקוּ אֶת הַתָּמִיד בְּכוֹס שֶׁל זָהָב. אַף עַל פִּי שֶׁהוּא מְבֻקָּר מִבָּעֶרֶב, מְבַקְּרִין אוֹתוֹ לְאוֹר הָאֲבוּקוֹת:",
      "מִי שֶׁזָּכָה בַתָּמִיד, מוֹשְׁכוֹ וְהוֹלֵךְ לְבֵית הַמִּטְבָּחַיִם, וּמִי שֶׁזָּכוּ בָאֵבָרִים הוֹלְכִין אַחֲרָיו. בֵּית הַמִּטְבָּחַיִם הָיָה לִצְפוֹנוֹ שֶׁל מִזְבֵּחַ, וְעָלָיו שְׁמֹנָה עַמּוּדִים נַנָּסִין, וּרְבִיעִית שֶׁל אֶרֶז עַל גַּבֵּיהֶן, וְאֻנְקְלָיוֹת שֶׁל בַּרְזֶל הָיוּ קְבוּעִין בָּהֶן, וּשְׁלשָׁה סְדָרִים הָיָה לְכָל אֶחָד וְאֶחָד, שֶׁבָּהֶן תּוֹלִין. וּמַפְשִׁיטִין עַל שֻׁלְחָנוֹת שֶׁל שַׁיִשׁ שֶׁבֵּין הָעַמּוּדִים:",
      "מִי שֶׁזָּכָה בְדִשּׁוּן מִזְבֵּחַ הַפְּנִימִי וְהַמְּנוֹרָה הָיוּ מַקְדִּימִין, וְאַרְבָּעָה כֵלִים בְּיָדָם, הַטֶּנִי וְהַכּוּז וּשְׁנֵי מַפְתְּחוֹת. הַטֶּנִי דוֹמֶה לְתַרְקָב גָּדוֹל שֶׁל זָהָב, מַחֲזִיק קַבַּיִן וָחֵצִי. וְהַכּוּז דּוֹמֶה לְקִיתוֹן גָּדוֹל שֶׁל זָהָב. וּשְׁנֵי מַפְתְּחוֹת, אֶחָד יוֹרֵד לְאַמַּת הַשֶּׁחִי וְאֶחָד פּוֹתֵחַ כֵּיוָן:",
      "בָּא לוֹ לַפִּשְׁפָּשׁ הַצְּפוֹנִי. וּשְׁנֵי פִשְׁפָּשִׁין הָיוּ לוֹ לַשַּׁעַר הַגָּדוֹל, אֶחָד בַּצָּפוֹן וְאֶחָד בַּדָּרוֹם. שֶׁבַּדָּרוֹם לֹא נִכְנַס בּוֹ אָדָם מֵעוֹלָם, וְעָלָיו הוּא מְפֹרָשׁ עַל יְדֵי יְחֶזְקֵאל (יחזקאל מד), וַיֹּאמֶר אֵלַי ה', הַשַּׁעַר הַזֶּה סָגוּר יִהְיֶה לֹא יִפָּתֵחַ וְאִישׁ לֹא יָבֹא בוֹ כִּי ה' אֱלֹהֵי יִשְׂרָאֵל בָּא בוֹ וְהָיָה סָגוּר. נָטַל אֶת הַמַּפְתֵּחַ וּפָתַח אֶת הַפִּשְׁפָּשׁ, נִכְנַס לַתָּא, וּמִן הַתָּא אֶל הַהֵיכָל, עַד שֶׁהוּא מַגִּיעַ לַשַּׁעַר הַגָּדוֹל. הִגִּיעַ לַשַּׁעַר הַגָּדוֹל, הֶעֱבִיר אֶת הַנֶּגֶר וְאֶת הַפּוֹתְחוֹת וּפְתָחוֹ. לֹא הָיָה שׁוֹחֵט הַשּׁוֹחֵט, עַד שֶׁשּׁוֹמֵעַ קוֹל שַׁעַר הַגָּדוֹל שֶׁנִּפְתָּח:",
      "מִירִיחוֹ הָיוּ שׁוֹמְעִין קוֹל שַׁעַר הַגָּדוֹל שֶׁנִּפְתָּח. מִירִיחוֹ הָיוּ שׁוֹמְעִין קוֹל הַמַּגְרֵפָה. מִירִיחוֹ הָיוּ שׁוֹמְעִין קוֹל הָעֵץ שֶׁעָשָׂה בֶן קָטִין מוּכְנִי לַכִּיּוֹר. מִירִיחוֹ הָיוּ שׁוֹמְעִין קוֹל גְּבִינִי כָּרוֹז. מִירִיחוֹ הָיוּ שׁוֹמְעִין קוֹל הֶחָלִיל. מִירִיחוֹ הָיוּ שׁוֹמְעִין קוֹל הַצֶּלְצָל. מִירִיחוֹ הָיוּ שׁוֹמְעִין קוֹל הַשִּׁיר. מִירִיחוֹ הָיוּ שׁוֹמְעִים קוֹל הַשּׁוֹפָר. וְיֵשׁ אוֹמְרִים, אַף קוֹל שֶׁל כֹּהֵן גָּדוֹל בְּשָׁעָה שֶׁהוּא מַזְכִּיר אֶת הַשֵּׁם בְּיוֹם הַכִּפּוּרִים. מִירִיחוֹ הָיוּ מְרִיחִים רֵיחַ פִּטּוּם הַקְּטֹרֶת. אָמַר רַבִּי אֱלִיעֶזֶר בֶּן דִּגְלַאי, עִזִּים הָיוּ לְבֵית אַבָּא בְּהַר מִכְוָר, וְהָיוּ מִתְעַטְּשׁוֹת מֵרֵיחַ פִּטּוּם הַקְּטֹרֶת:",
      "מִי שֶׁזָּכָה בְדִשּׁוּן מִזְבֵּחַ הַפְּנִימִי, נִכְנַס וְנָטַל הַטֶּנִי וְהִנִּיחוֹ לְפָנָיו, וְהָיָה חוֹפֵן וְנוֹתֵן לְתוֹכוֹ, וּבָאַחֲרוֹנָה כִּבֵּד אֶת הַשְּׁאָר לְתוֹכוֹ וְהִנִּיחוֹ וְיָצָא. מִי שֶׁזָּכָה בְדִשּׁוּן הַמְּנוֹרָה, נִכְנַס וּמָצָא שְׁנֵי נֵרוֹת מִזְרָחִיִּים דּוֹלְקִים, מְדַשֵּׁן אֶת הַשְּׁאָר וּמַנִּיחַ אֶת אֵלּוּ דּוֹלְקִין בִּמְקוֹמָן. מְצָאָן שֶׁכָּבוּ, מְדַשְּׁנָן וּמַדְלִיקָן מִן הַדּוֹלְקִים, וְאַחַר כָּךְ מְדַשֵּׁן אֶת הַשְּׁאָר. וְאֶבֶן הָיְתָה לִפְנֵי הַמְּנוֹרָה וּבָהּ שָׁלשׁ מַעֲלוֹת, שֶׁעָלֶיהָ הַכֹּהֵן עוֹמֵד וּמֵטִיב אֶת הַנֵּרוֹת. וְהִנִּיחַ אֶת הַכּוּז עַל מַעֲלָה שְׁנִיָּה וְיָצָא:"
